import{_ as o,C as a,o as i,c as l,j as s,a as u,E as t,a2 as n}from"./chunks/framework.TaNiW7i8.js";const b=JSON.parse('{"title":"Réglages","description":"","frontmatter":{"title":"Réglages"},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md"}'),g={name:"guide/settings.md"};function c(d,e,p,h,m,v){const r=a("Capture");return i(),l("div",null,[e[0]||(e[0]=s("h1",{id:"reglages",tabindex:"-1"},[u("Réglages "),s("a",{class:"header-anchor",href:"#reglages","aria-label":'Permalink to "Réglages"'},"​")],-1)),e[1]||(e[1]=s("p",null,"Les réglages rassemblent tout ce que vous pouvez ajuster dans Kessho : l'apparence, l'emplacement de la mémoire, la synchronisation, les raccourcis, les mises à jour. Ils tiennent sur une seule page, et la langue se change ailleurs, dans la barre latérale.",-1)),t(r,{name:"reglages-apparence",alt:"Les réglages d'apparence : le choix « Sombre » vient d'être coché et toute l'application bascule en thème sombre."}),e[2]||(e[2]=n('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>Cliquez <strong>Réglages</strong> en bas de la barre latérale (ou tapez <strong>⌘,</strong>) pour ouvrir l&#39;onglet <strong>Réglages</strong>.</p><ul><li><strong>À gauche</strong>, la liste des sections : <strong>Apparence</strong>, <strong>Mémoire</strong>, <strong>Synchronisation</strong>, <strong>Connecteurs MCP</strong>, <strong>Raccourcis</strong>, <strong>Mises à jour</strong>, <strong>Fonctionnalités</strong>, <strong>Cartographie</strong>, <strong>À propos</strong> et <strong>Réinitialisation</strong>. Un clic sur un nom amène à la section.</li><li><strong>À droite</strong>, la page : toutes les sections à la suite, le nom de la section en cours restant collé en haut pendant que vous défilez. L&#39;écran se rouvre là où vous l&#39;aviez laissé.</li></ul><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="choisir-l-apparence" tabindex="-1">Choisir l&#39;apparence <a class="header-anchor" href="#choisir-l-apparence" aria-label="Permalink to &quot;Choisir l&#39;apparence&quot;">​</a></h3><p>Dans <strong>Apparence</strong>, cliquez l&#39;une des trois tuiles : <strong>Système</strong>, <strong>Clair</strong> ou <strong>Sombre</strong>. Le changement est immédiat. <strong>Système</strong> suit le réglage de macOS ; le mode clair et le mode sombre sont traités à égalité. Le même choix est à portée de clic en haut à droite, à gauche de votre profil : un bouton fait tourner <strong>Système</strong>, <strong>Clair</strong> et <strong>Sombre</strong>.</p><p>La case « Demander confirmation avant de quitter avec du texte non enregistré » décide si Kessho vous pose la question quand vous quittez avec une note modifiée et non enregistrée. Elle est cochée par défaut.</p><h3 id="changer-la-langue" tabindex="-1">Changer la langue <a class="header-anchor" href="#changer-la-langue" aria-label="Permalink to &quot;Changer la langue&quot;">​</a></h3><p>La langue ne se règle pas dans les réglages : elle se choisit dans la barre latérale, en bas, avec le bouton qui porte le code de la langue (<strong>FR</strong>).</p>',9)),t(r,{name:"reglages-langue",alt:"Le sélecteur de langue de la barre latérale, ouvert : français, anglais, allemand, espagnol, russe."}),e[3]||(e[3]=n('<p>Le menu propose <strong>Français</strong>, <strong>English</strong>, <strong>Deutsch</strong>, <strong>Español</strong> et <strong>Русский</strong>. Cliquez celle que vous voulez.</p><h3 id="changer-ou-controler-la-memoire" tabindex="-1">Changer ou contrôler la mémoire <a class="header-anchor" href="#changer-ou-controler-la-memoire" aria-label="Permalink to &quot;Changer ou contrôler la mémoire&quot;">​</a></h3><p>La section <strong>Mémoire</strong> est un tableau de quatre lignes :</p><ul><li><strong>Emplacement</strong> : le dossier de votre mémoire. Cliquez <strong>Changer</strong> pour en choisir un autre dans le sélecteur de dossier ; le choix est enregistré aussitôt. Fermer le sélecteur sans choisir ne change rien.</li><li><strong>Contenu</strong> : ce que contient la mémoire, par exemple « 13 notes · 16 fichiers · 89 Ko ».</li><li><strong>Ancienne installation</strong> : cette ligne n&#39;apparaît que si Kessho en détecte une qui n&#39;est pas encore reprise. Elle vous renvoie au bandeau de l&#39;<a href="/Kessho/guide/home.html">Accueil</a> pour reprendre la migration.</li><li><strong>Sauvegarde</strong> : dit si la mémoire est protégée par git. « Aucune — vos fichiers vous appartiennent », « Dépôt git local, sans distant » ou « Dépôt git synchronisé avec … ».</li></ul><p>Pour choisir une mémoire la première fois, voir <a href="/Kessho/guide/vault.html">Choisir sa mémoire</a>.</p><h3 id="synchroniser-la-memoire" tabindex="-1">Synchroniser la mémoire <a class="header-anchor" href="#synchroniser-la-memoire" aria-label="Permalink to &quot;Synchroniser la mémoire&quot;">​</a></h3><p>La section <strong>Synchronisation</strong> reprend l&#39;état du dépôt et ses gestes : <strong>Synchroniser</strong>, <strong>Récupérer</strong>, <strong>Pousser</strong>, les changements à commiter, le distant et l&#39;automatisme des agents. Tout est décrit dans <a href="/Kessho/guide/sync.html">Synchronisation</a>.</p><h3 id="connecter-vos-agents" tabindex="-1">Connecter vos agents <a class="header-anchor" href="#connecter-vos-agents" aria-label="Permalink to &quot;Connecter vos agents&quot;">​</a></h3><p>La section <strong>Connecteurs MCP</strong> liste les clients d&#39;IA détectés sur votre ordinateur et dit lesquels portent Kessho. Voir <a href="/Kessho/guide/agents.html">Connecter ses agents</a>.</p><h3 id="lire-les-raccourcis-changer-ceux-de-l-editeur" tabindex="-1">Lire les raccourcis, changer ceux de l&#39;éditeur <a class="header-anchor" href="#lire-les-raccourcis-changer-ceux-de-l-editeur" aria-label="Permalink to &quot;Lire les raccourcis, changer ceux de l&#39;éditeur&quot;">​</a></h3><p>La section <strong>Raccourcis</strong> a deux tableaux.</p>',11)),t(r,{name:"reglages-raccourcis",alt:"La section Raccourcis des Réglages : le raccourci « Gras » est en cours de modification, l'écran attend la nouvelle combinaison (Échap annule)."}),e[4]||(e[4]=n('<ul><li>Le premier liste les raccourcis de l&#39;application : <strong>⌘K</strong> ouvrir la recherche, <strong>⌘,</strong> ouvrir les réglages, <strong>⌘W</strong> fermer l&#39;onglet, <strong>⌘B</strong> afficher ou masquer la barre latérale, <strong>⌥←</strong> et <strong>⌥→</strong> onglet précédent ou suivant. Il se lit seulement. Sous Windows, <strong>⌘</strong> devient <strong>Ctrl</strong> et <strong>⌥</strong> devient <strong>Alt</strong>.</li><li>Le second, <strong>Dans l&#39;éditeur</strong>, liste les raccourcis de l&#39;éditeur de notes. Ceux-là se changent : cliquez <strong>Modifier</strong> en face d&#39;un geste, tapez la nouvelle combinaison, <strong>Échap</strong> annule. Une combinaison est refusée, avec la raison, si elle ne contient pas <strong>⌘</strong> (ou <strong>Ctrl</strong>), si le système la réserve ou si un autre geste l&#39;utilise déjà. <strong>Rétablir</strong> remet la touche d&#39;origine, <strong>Tout rétablir</strong> remet toutes les touches.</li></ul><p>Les raccourcis ne s&#39;appliquent pas pendant la saisie d&#39;un texte. La liste des gestes de l&#39;éditeur est dans <a href="/Kessho/guide/atom.html">Atome et éditeur</a>.</p><h3 id="mettre-a-jour-kessho" tabindex="-1">Mettre à jour Kessho <a class="header-anchor" href="#mettre-a-jour-kessho" aria-label="Permalink to &quot;Mettre à jour Kessho&quot;">​</a></h3><p>Dans <strong>Mises à jour</strong> :</p><ol><li>Lisez la <strong>Version installée</strong>.</li><li>Choisissez le <strong>Canal</strong>. Un canal qui ne peut pas être atteint est marqué « Canal indisponible », avec la raison quand on la connaît.</li><li>Cliquez <strong>Vérifier</strong>. Le résultat dit « À jour — … est la dernière version publiée. » ou « Version … disponible. ».</li><li>Si une version est disponible, cliquez <strong>Installer et redémarrer</strong>. Si des processus Kessho utilisés par vos agents IA tournent encore, Kessho vous le dit : <strong>Fermer et installer</strong> les ferme avant de remplacer le programme.</li></ol><p>Au lancement, Kessho interroge une fois le canal public. S&#39;il existe une version plus récente, un bandeau « Version … disponible » apparaît en haut : <strong>Voir la mise à jour</strong> ouvre cette section, <strong>Plus tard</strong> le masque jusqu&#39;au prochain lancement. Rien n&#39;est installé sans votre clic. Pour couper cette vérification, décochez <strong>Chercher une mise à jour publique au lancement</strong>, dans la même section.</p><h3 id="consulter-les-paliers" tabindex="-1">Consulter les paliers <a class="header-anchor" href="#consulter-les-paliers" aria-label="Permalink to &quot;Consulter les paliers&quot;">​</a></h3><p><strong>Fonctionnalités</strong> affiche les <strong>Paliers de licence</strong> : ce que chaque palier autorise. C&#39;est en lecture seule, ces paliers ne sont pas des réglages.</p><h3 id="cartographier-le-code-d-un-projet" tabindex="-1">Cartographier le code d&#39;un projet <a class="header-anchor" href="#cartographier-le-code-d-un-projet" aria-label="Permalink to &quot;Cartographier le code d&#39;un projet&quot;">​</a></h3><p><strong>Cartographie</strong> mesure à quel point le code d&#39;un projet de la mémoire est décrit.</p><ol><li>Écrivez le nom d&#39;un projet dans <strong>Projet de la mémoire</strong>, puis cliquez <strong>Scanner</strong>.</li><li>Lisez la <strong>Couverture</strong> (« N fichiers décrits sur M »), les <strong>Candidats non documentés</strong>, les <strong>Références mortes</strong> et les <strong>Entrées obsolètes</strong>.</li><li>Pour ajouter un dossier au scan, écrivez-le sous <strong>Ajouter une zone à scanner</strong> et cliquez <strong>Ajouter</strong>.</li><li>Pour nettoyer, cliquez <strong>Aperçu de la réparation</strong> : l&#39;aperçu dit combien de références mortes seraient retirées. <strong>Appliquer la réparation</strong> l&#39;exécute.</li></ol><h3 id="voir-la-version-et-les-mentions" tabindex="-1">Voir la version et les mentions <a class="header-anchor" href="#voir-la-version-et-les-mentions" aria-label="Permalink to &quot;Voir la version et les mentions&quot;">​</a></h3><p><strong>À propos</strong> donne le <strong>Produit</strong>, la <strong>Version</strong> et la <strong>Plateforme</strong>. <strong>Afficher les mentions tierces</strong> déplie les licences des composants libres que Kessho embarque ; <strong>Masquer les mentions tierces</strong> les replie.</p><h3 id="reinitialiser" tabindex="-1">Réinitialiser <a class="header-anchor" href="#reinitialiser" aria-label="Permalink to &quot;Réinitialiser&quot;">​</a></h3><p><strong>Réinitialisation</strong> relance l&#39;assistant de premier lancement : cliquez <strong>Relancer l&#39;assistant d&#39;Onboarding</strong>. La configuration est remise à zéro ; la mémoire et son contenu ne sont pas touchés. Voir <a href="/Kessho/guide/first-run.html">Premier lancement</a>.</p>',15))])}const f=o(g,[["render",c]]);export{b as __pageData,f as default};
